pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 /* seed */) public {
        // General rule: the getter owner() resolves the owner from the
        // immutable-arg word at offset 0x0, which is always a well-defined,
        // nonzero address derived from the contract's immutable-arg data.
        // The mutant reads offset 0x14 instead (the collateral word), so for
        // this call context it returns a different (here zero) address.
        bool ok;
        address returned;
        try c.owner() returns (address o) {
            ok = true;
            returned = o;
        } catch {
            ok = false;
        }
        assertTrue(ok && returned != address(0));
    }
}

