pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 x) public {
        // keep the low 12 bytes nonzero so the offset-0x14 word is nonzero and differs
        vm.assume(x & 0xffffffffffffffffffffffff != 0);

        // calldata: owner selector || bytes32(x) || uint16 trailer 0x0022 (=34)
        // immutable-args offset = 38 - (34 + 2) = 0
        bytes memory cd = abi.encodePacked(C.owner.selector, bytes32(x), bytes2(uint16(34)));
        (bool ok, bytes memory ret) = address(c).call(cd);

        // P reads word at offset 0x0: calldataload(0) = selector << 224, then shr(0x60)
        uint256 expected0 = uint256(uint32(C.owner.selector)) * 2 ** 128;

        assertTrue(ok && abi.decode(ret, (address)) == address(uint160(expected0)));
    }
}

