pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function wordAt(bytes memory b, uint256 off) internal pure returns (uint256 w) {
        assembly {
            w := mload(add(add(b, 0x20), off))
        }
    }

    function testFuzz_property(bytes memory data) public {
        // Admissible domain: the tail is long enough, and the immutable-args
        // offset L (encoded in the last 2 bytes of the full calldata) puts both
        // the offset word and the offset+0x14 word fully inside the calldata,
        // and the two words differ in their top 20 bytes.
        vm.assume(data.length >= 2);

        bytes memory total = abi.encodePacked(c.owner.selector, data);
        uint256 len = total.length;

        uint256 L;
        assembly {
            L := shr(240, mload(add(add(total, 0x20), sub(len, 2))))
        }
        vm.assume(L + 2 <= len);

        uint256 offset = len - L - 2;
        vm.assume(offset + 0x34 <= len);

        uint256 w0 = wordAt(total, offset);
        uint256 w1 = wordAt(total, offset + 0x14);
        vm.assume(uint160(w0 >> 96) != uint160(w1 >> 96));

        address expected;
        assembly {
            expected := shr(0x60, mload(add(add(total, 0x20), offset)))
        }

        (bool ok, bytes memory ret) = address(c).call(total);

        assertTrue(
            ok && ret.length == 32 && abi.decode(ret, (address)) == expected,
            "owner() must return the top-20 bytes of the word at the immutable-args offset"
        );
    }
}

