import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory, ERC20} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    CoolerFactory factory;
    ERC20Mock collateralToken;
    ERC20Mock debtToken;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
        collateralToken = new ERC20Mock("COL", "COL", 18);
        debtToken = new ERC20Mock("DBT", "DBT", 18);
    }

    C c;

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(debtToken));
        vm.assume(actor != address(collateralToken));

        vm.prank(actor);
        address cooler = factory.generateCooler(collateralToken, debtToken);

        // General rule: the clone's owner() is always the address that generated it.
        assertTrue(C(cooler).owner() == actor);
    }
}

