pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
        // clones are copies of the same implementation
        assert(address(factory.coolerImplementation()) == address(c));
    }

    function testFuzz_property(
        address actor,
        address collateralToken,
        address debt1,
        address debt2
    ) public {
        vm.assume(debt1 != debt2);
        vm.prank(actor);
        address cooler1 = factory.generateCooler(
            ERC20(collateralToken), ERC20(debt1)
        );
        vm.prank(actor);
        address cooler2 = factory.generateCooler(
            ERC20(collateralToken), ERC20(debt2)
        );
        // General rule: owner() is immutable-arg offset 0x0 = the generating caller,
        // so both coolers owned by the same actor must report the same owner.
        assertTrue(
            C(cooler1).owner() == C(cooler2).owner(),
            "owner() must not depend on the debt token"
        );
    }
}

