pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory, ERC20} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    CoolerFactory factory;
    C c;

    function setUp() public {
        c = new C();
        factory = new CoolerFactory();
    }

    function testFuzz_property(
        address callerA,
        address callerB,
        address collateralToken,
        address debtToken
    ) public {
        vm.assume(callerA != address(0) && callerB != address(0));
        vm.assume(collateralToken != address(0) && debtToken != address(0));
        vm.assume(callerA != callerB);

        vm.prank(callerA);
        address coolerA = factory.generateCooler(
            ERC20(collateralToken), ERC20(debtToken)
        );

        vm.prank(callerB);
        address coolerB = factory.generateCooler(
            ERC20(collateralToken), ERC20(debtToken)
        );

        // General rule: a cooler's owner is the caller that generated it,
        // so two distinct callers of the same pair get distinct owners.
        assertTrue(
            C(coolerA).owner() != C(coolerB).owner(),
            "owner() must identify the generating caller"
        );
    }
}

