pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address ownerArg, address debtArg) public {
        vm.assume(ownerArg != debtArg);
        // Build calldata: selector + immutable-args block of 80 bytes:
        // owner @ +0x00, collateral @ +0x14, debt @ +0x28, "factory" @ +0x3c.
        // The last 2 bytes of calldata must encode (totalArgsLen) so that
        // _getImmutableArgsOffset() yields 4 (args start right after selector):
        // total calldatasize = 4 + 80 = 84, need offset = 84 - (x + 2) = 4 => x = 78.
        bytes memory data = abi.encodePacked(
            c.owner.selector,
            bytes20(ownerArg),
            bytes20(address(0x1)),
            bytes20(debtArg),
            bytes20(0x000000000000000000000000000000000000004e) // last two bytes 0x004e = 78
        );
        (bool ok, bytes memory ret) = address(c).call(data);
        assertTrue(ok && ret.length == 32 && address(uint256(bytes32(ret))) == ownerArg);
    }
}

