pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        address owner_,
        address collateral_,
        address debt_,
        address factory_
    ) public {
        // Keep the immutable args in a wide but admissible domain: the
        // distinguishing rule requires owner != factory (non-zero too so the
        // returned value is a meaningful address).
        vm.assume(owner_ != address(0));
        vm.assume(factory_ != address(0));
        vm.assume(owner_ != factory_);

        // Mimic the factory clone's calldata: 4-byte selector, the four packed
        // immutable args appended, then the 2-byte length of the args payload
        // (4 * 32 = 128 bytes plus the length word = 130).
        bytes memory calldata_ = abi.encodePacked(
            bytes4(0x12345678),
            owner_,
            collateral_,
            debt_,
            factory_,
            uint16(130)
        );

        (bool ok, bytes memory ret) = address(c).call(calldata_);
        assertTrue(ok, "owner() call reverted");
        address returnedOwner = abi.decode(ret, (address));

        // General rule: owner() returns the immutable owner argument, which is
        // different from the immutable factory argument for every admissible
        // input. The mutant reads offset 0x3c and returns the factory instead.
        assertTrue(returnedOwner == owner_ && returnedOwner != factory_, "owner() must return the owner immutable arg");
    }
}

