pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C impl;

    function setUp() public {
        impl = new C();
    }

    function testFuzz_property(address owner_, address collateral_, address debt_, address factory_) public {
        vm.assume(owner_ != factory_);
        vm.assume(owner_ != address(0));
        vm.assume(factory_ != address(0));

        bytes memory data = abi.encodePacked(owner_, collateral_, debt_, factory_);
        address cloneAddr = _clone(address(impl), data);
        C c = C(cloneAddr);

        assertTrue(c.owner() == owner_ && c.owner() != c.factory());
    }

    function _clone(address implementation, bytes memory data) internal returns (address instance) {
        uint16 extraLength = uint16(data.length + 2);
        uint16 runSize = uint16(0x41 + data.length + 2 - 10);
        bytes memory code = abi.encodePacked(
            hex"61", runSize,
            hex"3d81600a3d39f33d3d3d3d363d3d3761", extraLength,
            hex"603736393661", extraLength,
            hex"013d73", implementation, hex"5af43d3d93803e603557fd5bf3",
            data, extraLength
        );
        assembly {
            instance := create(0, add(code, 32), mload(code))
        }
        require(instance != address(0));
    }
}

