import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // The seed keeps the fuzz domain wide; owner() is pure and reads its
        // value from the calldata-relative immutable-args offset, which is
        // determined by the call itself, not by the seed.
        vm.assume(seed < type(uint256).max);
        // General rule: owner() must always return a non-zero address (the
        // first immutable arg, read at offset 0x0). The mutant reads offset
        // 0x3c, past the end of the calldata, so it returns address(0).
        bool ok;
        address returned;
        try c.owner() returns (address o) {
            ok = true;
            returned = o;
        } catch {
            ok = false;
        }
        assertTrue(ok && returned != address(0));
    }
}
